<script setup lang="ts">
import { onMounted, ref, watch } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import PageHeader from "@/components/PageHeader.vue";
import { getAuditDetail, listAudit, type AuditEvent } from "@/services/administracion";

const items = ref<AuditEvent[]>([]); const page = ref(1); const search = ref(""); const desde = ref(""); const hasta = ref(""); const idUsuario = ref(""); const evento = ref(""); const resultado = ref("all");
const pagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 }); const loading = ref(false); const error = ref(""); const detailLoading = ref(false); const detailError = ref(""); const selected = ref<AuditEvent | null>(null); const detail = ref<Record<string, unknown> | null>(null);
const message = (e: unknown) => e instanceof Error ? e.message : "Ocurrió un error inesperado";
async function load() { loading.value = true; error.value = ""; try { const result = await listAudit({ page: page.value, pageSize: 10, search: search.value, desde: desde.value, hasta: hasta.value, idUsuario: idUsuario.value, evento: evento.value, resultado: resultado.value }); items.value = result.items; pagination.value = result.pagination; } catch (e) { error.value = message(e); } finally { loading.value = false; } }
async function showDetail(item: AuditEvent) { selected.value = item; detail.value = null; detailError.value = ""; detailLoading.value = true; try { detail.value = await getAuditDetail(item.fuente, item.idEvento); } catch (e) { detailError.value = message(e); } finally { detailLoading.value = false; } }
watch([resultado], () => { page.value = 1; void load(); }); onMounted(() => void load());
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración' }, { label: 'Auditoría' }]" />
  <PageHeader eyebrow="Administración" title="Auditoría" description="Consulta de bitácoras administrativas e intentos de autenticación realmente registrados." action-label="Actualizar" @action="load" />
  <div v-if="error" class="bo-state bo-state-error" role="alert">{{ error }} <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar bo-toolbar-wrap" @submit.prevent="page = 1; load()"><input v-model="search" placeholder="Usuario, módulo o entidad..." aria-label="Buscar" /><input v-model="desde" type="date" aria-label="Desde" /><input v-model="hasta" type="date" aria-label="Hasta" /><input v-model="idUsuario" type="number" min="1" placeholder="ID usuario" aria-label="Filtrar por ID de usuario" /><input v-model="evento" placeholder="Evento" aria-label="Filtrar evento" /><select v-model="resultado" aria-label="Resultado"><option value="all">Todos los resultados</option><option value="correcto">Correctos</option><option value="fallido">Fallidos</option></select><button class="bo-btn bo-btn-primary">Filtrar</button></form>
    <div v-if="loading" class="bo-state">Cargando eventos...</div><div v-else-if="!items.length" class="bo-state"><strong>No hay eventos registrados para estos filtros.</strong><span>El listado no utiliza datos simulados.</span></div><div v-else class="bo-table-wrap"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Evento</th><th>Módulo / entidad</th><th>Resultado</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="`${item.fuente}-${item.idEvento}`"><td>{{ new Date(item.fecha).toLocaleString() }}</td><td>{{ item.usuario }}<br /><small>ID {{ item.idUsuario ?? 'no identificado' }}</small></td><td>{{ item.evento }}</td><td>{{ item.modulo }} / {{ item.entidad }}</td><td><span v-if="item.resultado" :class="item.resultado === 'correcto' ? 'bo-status bo-status-active' : 'bo-status bo-status-inactive'">{{ item.resultado }}</span><span v-else>—</span></td><td><button class="bo-action" @click="showDetail(item)">Detalles</button></td></tr></tbody></table></div>
    <footer class="bo-pagination"><span>{{ pagination.total }} eventos · Página {{ pagination.page }} de {{ Math.max(pagination.totalPages, 1) }}</span><div><button class="bo-page-button" :disabled="page <= 1 || loading" @click="page--; load()">Anterior</button><button class="bo-page-button" :disabled="page >= pagination.totalPages || loading" @click="page++; load()">Siguiente</button></div></footer>
  </section>
  <div v-if="selected" class="bo-modal-backdrop" @click.self="selected = null"><section class="bo-modal"><header><div><span class="bo-eyebrow">{{ selected.fuente }} · {{ new Date(selected.fecha).toLocaleString() }}</span><h2>Detalle de auditoría</h2></div><button class="bo-close" type="button" aria-label="Cerrar" @click="selected = null">×</button></header><div v-if="detailLoading" class="bo-state">Cargando detalle...</div><p v-else-if="detailError" class="bo-form-error">{{ detailError }}</p><dl v-else-if="detail" class="bo-audit-detail"><template v-for="(value, key) in detail" :key="key"><dt>{{ key }}</dt><dd><pre>{{ typeof value === 'object' && value !== null ? JSON.stringify(value, null, 2) : String(value ?? '—') }}</pre></dd></template></dl></section></div>
  <p class="bo-form-note">Actualmente se consultan Auditoria.tblBitacoras y Auditoria.tblIntentosAutenticacion. Otros eventos de negocio no se presentan como auditados hasta instrumentarlos.</p>
</template>
